`api_usage.py` already logs by `caller`. Extend its records with the routed `tier` so the dashboard shows per-tier spend — useful for spotting accidental TRUSTED→OPEN mis-routes after the fact.

```js
async function redraftViaHaiku(rawDraft, voiceProfile) {
  const { redactedText, mapping, unknownEntities, hardBlock } = piiRedactor.redact(rawDraft);
  if (hardBlock) throw new Error(`PII hard-block: ${hardBlock}`);
  const tier = routing.tierFor('voice_redraft');  // -> 'TRUSTED'
  if (!piiRedactor.safeForTier({mapping, unknownEntities}, tier)) {
    throw new Error('Routing refused by PII redactor.');
  }
  const model = routing.modelFor('voice_redraft');
  const raw = await callModel(model, redactedText);
  const restored = piiRedactor.restore(raw, mapping);
  return voiceDriftLinter.lint(restored, voiceProfile);  // runs on un-redacted
}
```

**Order:** redact → safe_for_tier → model call → restore → voice-drift linter.
